import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    # Parse JSON data
    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Malformed JSON data")

    # Check if data is empty
    if not data:
        raise ValueError("Empty JSON data")

    # Validate and process data
    records = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each entry must be a dictionary")

        if "Country" not in item or "Population" not in item:
            raise ValueError("Each entry must have 'Country' and 'Population' keys")

        country = item["Country"]
        population = item["Population"]

        # Validate country name
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")

        # Validate population
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")

        if population < 0:
            raise ValueError("Population must be non-negative")

        # Round down float populations to nearest integer
        if isinstance(population, float):
            population = math.floor(population)

        records.append({"Country": country, "Population": int(population)})

    # Create DataFrame
    df = pd.DataFrame(records, columns=["Country", "Population"])

    # Ensure output directory exists
    if not os.path.exists(output_dir):
        try:
            os.makedirs(output_dir)
        except OSError:
            raise IOError(f"Cannot create directory: {output_dir}")

    # Write CSV file
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except (IOError, OSError) as e:
        raise IOError(f"Cannot write to file: {file_path}")

    return file_path, df

import urllib.request
import os
import csv
import collections

def task_func(url, column_name, csv_file_path):
    # Download the CSV file
    try:
        urllib.request.urlretrieve(url, csv_file_path)
    except Exception as e:
        raise e

    # Read the CSV file and count occurrences
    try:
        with open(csv_file_path, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                # Empty file or no headers
                if column_name not in (reader.fieldnames or []):
                    os.remove(csv_file_path)
                    raise ValueError(f"The provided column_name '{column_name}' does not exist in the CSV file.")
                return {}

            if column_name not in reader.fieldnames:
                os.remove(csv_file_path)
                raise ValueError(f"The provided column_name '{column_name}' does not exist in the CSV file.")

            counter = collections.Counter()
            for row in reader:
                value = row.get(column_name, '')
                counter[value] += 1

            return dict(counter)
    finally:
        # Delete the downloaded file
        if os.path.exists(csv_file_path):
            os.remove(csv_file_path)
